package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int64 {
	b := next()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	var r int64
	for _, c := range b {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	a, b, c, x, y := nextInt(), nextInt(), nextInt(), nextInt(), nextInt()
	best := int64(-1)
	for _, z := range []int64{0, min(x, y), max(x, y)} {
		cost := z*c + max(0, x-z)*a + max(0, y-z)*b
		if best < 0 || cost < best {
			best = cost
		}
	}
	w.WriteString(strconv.FormatInt(best, 10) + "\n")
}
